`timescale 1ns/1ps
`default_nettype none
// Golden image generated by independent Python sequential ISA interpreter.
// Actual RTL is simulated with configurable backpressure and compared against
// every architectural register and all 1024 memory words.
module tb_random_reference_rv32i;
    parameter integer DATA_LATENCY=1;
    parameter integer DATA_MAX_EXTRA=0;
    reg clk=0,rst_n=0;
    always #5 clk=~clk;
    pipeline_core #(.DATA_LATENCY(DATA_LATENCY),.DATA_MAX_EXTRA(DATA_MAX_EXTRA))
        dut(.clk(clk),.rst_n(rst_n));
    reg [31:0] prog_words[0:1023];
    reg [31:0] initial_mem[0:1023];
    reg [31:0] expected_regs[0:31];
    reg [31:0] expected_mem[0:1023];
    integer n,cycles,issued=0,responses=0;
    reg [8*256-1:0] vcd_path;
    always @(posedge clk) if(rst_n) begin
        if(dut.mem_req_valid && dut.mem_req_ready) issued=issued+1;
        if(dut.mem_rsp_valid) responses=responses+1;
        if(responses>issued) $fatal(1,"Response without request");
        if(issued-responses>1) $fatal(1,"Multiple outstanding requests");
    end
    initial begin
        for(n=0;n<1024;n=n+1) begin
            dut.imem[n]=32'h00000013;
            prog_words[n]=32'h00000013;
            dut.mem_model.words[n]=0;
        end
        $readmemh("program.hex",prog_words);
        $readmemh("initial_mem.hex",initial_mem);
        $readmemh("expected_regs.hex",expected_regs);
        $readmemh("expected_mem.hex",expected_mem);
        for(n=0;n<1024;n=n+1) begin
            dut.imem[n]=prog_words[n];
            dut.mem_model.words[n]=initial_mem[n];
        end
        if($value$plusargs("vcd=%s",vcd_path))begin
            // Intentional minimal signal set: authentic waveform without
            // duplicating a huge architectural-memory image into the VCD.
            $dumpfile(vcd_path);
            $dumpvars(0,clk,rst_n,dut.pc,dut.mem_req_valid,dut.mem_req_ready,
                      dut.mem_rsp_valid,dut.mem_hold,dut.ex_mem_alu_res,
                      dut.mem_model.busy,dut.rf_we,dut.rf_wr,dut.rf_wd);
        end
        repeat(3) @(negedge clk);
        rst_n=1;
        cycles=0;
        // Generator emits no backward branches. End marker is 0x00000013.
        while(dut.pc < 1024 && cycles<5000) begin
            @(negedge clk);
            cycles=cycles+1;
            if(^dut.pc===1'bx) $fatal(1,"PC became X");
        end
        if(cycles>=5000) $fatal(1,"random program progress timeout");
        repeat(25+DATA_LATENCY+DATA_MAX_EXTRA) @(negedge clk);
        for(n=0;n<32;n=n+1)
            if(dut.rf.regs[n]!==expected_regs[n])
                $fatal(1,"reg x%0d got %h expected %h",n,dut.rf.regs[n],expected_regs[n]);
        for(n=0;n<1024;n=n+1)
            if(dut.mem_model.words[n]!==expected_mem[n])
                $fatal(1,"mem[%0d] got %h expected %h",n,dut.mem_model.words[n],expected_mem[n]);
        if(issued != responses) $fatal(1,"unbalanced requests=%0d responses=%0d",issued,responses);
        if(issued<25) $fatal(1,"stress generated too few memory operations");
        $display("PASS random reference latency=%0d extra=%0d cycles=%0d requests=%0d responses=%0d 1056 architectural checks",
                DATA_LATENCY, DATA_MAX_EXTRA, cycles,issued,responses);
        $finish;
    end
endmodule
`default_nettype wire
